import java.io.BufferedInputStream
import java.io.PrintWriter
import java.util.StringTokenizer

private const val MAXN = 1000 * 100 + 5

private val adj = Array(MAXN) { IntArray(0) }
private val adjr = Array(MAXN) { IntArray(0) }
private val mark = IntArray(MAXN)
private val ans = IntArray(MAXN)
private val st = IntArray(MAXN)

private fun dfs1(x: Int) {
    mark[x] = 1
    ans[x]++
    for (u in adj[x]) {
        if (mark[u] == 0) dfs1(u)
    }
}

private fun dfs2(x: Int) {
    mark[x] = 1
    ans[x]++
    if (st[x] == 1) return
    for (u in adjr[x]) {
        if (mark[u] == 0) dfs2(u)
    }
}

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var len = 0
    private var ptr = 0

    private fun read(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextInt(): Int {
        var c = read()
        while (c <= 32 && c >= 0) c = read()
        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = read()
        }
        var res = 0
        while (c > 32) {
            res = res * 10 + (c - '0'.code)
            c = read()
        }
        return res * sign
    }
}

fun main() {
    val fs = FastScanner()
    val out = PrintWriter(System.out)

    val n = fs.nextInt()
    val m = fs.nextInt()

    for (i in 0 until n) {
        st[i] = fs.nextInt()
    }

    val tempAdj = Array(n) { mutableListOf<Int>() }
    val tempAdjr = Array(n) { mutableListOf<Int>() }

    for (i in 0 until m) {
        var u = fs.nextInt()
        var v = fs.nextInt()
        u--
        v--
        tempAdj[u].add(v)
        tempAdjr[v].add(u)
    }

    for (i in 0 until n) {
        adj[i] = tempAdj[i].toIntArray()
        adjr[i] = tempAdjr[i].toIntArray()
    }

    for (i in 0 until n) {
        if (mark[i] == 0 && st[i] == 1) dfs1(i)
    }

    for (i in 0 until n) {
        mark[i] = 0
    }

    for (i in 0 until n) {
        if (mark[i] == 0 && st[i] == 2) dfs2(i)
    }

    for (i in 0 until n) {
        if (ans[i] == 2) out.println(1) else out.println(0)
    }

    out.flush()
}

